func tZeros(b *port.Buf, n int32) int32 {
	// The caller's part of `cc-decode`'s contract: `n` zero bytes to paint on.
	var i int32 = 0
	for i < n {
		port.BufPush(b, 0)
		i += 1
	}
	return 0
}

func tStrip(emonT *testing.T, t []byte, k int32, flags int32, out *port.Buf, msg string) int32 {
	// Decode the one strip of a 48 x 36 bilevel fixture; the status of the decoder.
	var r *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var s int32 = tiffcheck.TcCheck(t, 0, 1, r)
	port.AssertEq(emonT, s, 0, msg)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrNchunks()), 1, msg)
	var off int32 = port.CellsAt(r, port.CellsAt(r, tiffcheck.TrOffsAt()))
	var n int32 = port.CellsAt(r, port.CellsAt(r, tiffcheck.TrLensAt()))
	tZeros(out, 216)
	return ccitt.CcDecode(t, off, off+n, k, 48, 36, flags, out, ws)
}

func tSame(emonT *testing.T, t []byte, k int32, none []byte, msg string) int32 {
	// The strip of `t` decoded is the picture the uncompressed file `none` holds, bit for bit (libtiff reads a CCITT black run as 1 bits whatever the photometric: D188).
	var got *port.Buf = port.NewBuf()
	var r *port.Cells = port.NewCells()
	var s int32 = tiffcheck.TcCheck(none, 0, 1, r)
	var off int32 = port.CellsAt(r, port.CellsAt(r, tiffcheck.TrOffsAt()))
	var i int32 = 0
	port.AssertEq(emonT, tStrip(emonT, t, k, 0, got, msg), 0, msg)
	port.AssertEq(emonT, s, 0, msg)
	port.AssertEq(emonT, port.BufLen(got), 216, msg)
	for i < 216 {
		port.AssertEq(emonT, port.BufAt(got, i), port.BlobU8(none, off+i), msg)
		i += 1
	}
	return 0
}

func TestCcittDecodesTheTiffFixtures(emonT *testing.T) {
	tSame(emonT, port.TestFile("image/tiff-bilevel-g4.tif"), -1, port.TestFile("image/tiff-bilevel-none.tif"), "Group 4")
	tSame(emonT, port.TestFile("image/tiff-bilevel-g3.tif"), 0, port.TestFile("image/tiff-bilevel-none.tif"), "Group 3, one-dimensional")
}

func tRawStrip(emonT *testing.T, t []byte, off int32, k int32, none []byte, msg string) int32 {
	// A refused TIFF (validator says no) whose strip starts at `off` and runs to the end of the strips: the decoder reads
	// what the validator will not hand over: Group 3 two-dimensional, and EOLs padded with fill bits.
	var got *port.Buf = port.NewBuf()
	var ws *port.Cells = port.NewCells()
	var r *port.Cells = port.NewCells()
	var s int32 = tiffcheck.TcCheck(none, 0, 1, r)
	var woff int32 = port.CellsAt(r, port.CellsAt(r, tiffcheck.TrOffsAt()))
	var i int32 = 0
	port.AssertEq(emonT, s, 0, msg)
	tZeros(got, 216)
	port.AssertEq(emonT, ccitt.CcDecode(t, off, port.BlobLen(t), k, 48, 36, 0, got, ws), 0, msg)
	port.AssertEq(emonT, port.BufLen(got), 216, msg)
	for i < 216 {
		port.AssertEq(emonT, port.BufAt(got, i), port.BlobU8(none, woff+i), msg)
		i += 1
	}
	return 0
}

func TestCcittReadsWhatTheValidatorRefuses(emonT *testing.T) {
	tRawStrip(emonT, port.TestFile("image/tiff-bilevel-g3-2d.tif"), 8, 1, port.TestFile("image/tiff-bilevel-none.tif"), "Group 3, two-dimensional")
	tRawStrip(emonT, port.TestFile("image/tiff-bilevel-g3-fill.tif"), 8, 0, port.TestFile("image/tiff-bilevel-none.tif"), "Group 3 with fill bits before the EOLs")
}

func TestExifReader(emonT *testing.T) {
	// The first directory of an EXIF blob: orientation 1..8 and the two resolutions; anything else says (1, 0, 0).
	var r *port.Cells = port.NewCells()
	tiffcheck.TcExif(port.HexBlob("49492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000"), 0, 70, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 6, "orientation")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEx()), 30000, "horizontal resolution")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEy()), 30000, "vertical resolution")
	tiffcheck.TcExif(port.HexBlob("010203040549492a000800000004001201030001000000060000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000002c01000001000000"), 5, 70, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 6, "orientation, in a blob that starts later")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEx()), 30000, "... and its resolution")
	tiffcheck.TcExif(port.HexBlob("49492a000800000004001201030001000000010000001a010500010000003e0000001b010500010000003e000000280103000100000002000000000000009600000001000000"), 0, 70, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 1, "orientation 1")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEx()), 15000, "150 dpi")
	tiffcheck.TcExif(port.HexBlob("4d4d002b00080000"), 0, 8, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 1, "BigTIFF says nothing")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEx()), 0, "... of the resolution")
	tiffcheck.TcExif(port.HexBlob("49492a00"), 0, 4, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 1, "a blob of four bytes says nothing")
	tiffcheck.TcExif(port.HexBlob("49492a00ffffffff0000"), 0, 10, r)
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEo()), 1, "a directory outside the blob says nothing")
	port.AssertEq(emonT, port.CellsAt(r, tiffcheck.TrEy()), 0, "... of the resolution")
}
